import {DemoStore} from './data.js';
import {money,fullMoney,toPaisa,today,uid,balances,summary,activeTransactions,inPeriod,cashflow,expenseGroups,csv,invoiceStatus,CATEGORIES} from './domain.js';
import {firebaseConfig} from './firebase-config.js';

const $=s=>document.querySelector(s), app=$('#app');
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',transactions:'<path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/>',wallet:'<path d="M20 7V5a2 2 0 0 0-2-2H6a3 3 0 0 0 0 6h14v11H6a3 3 0 0 1-3-3V6"/><path d="M20 11h-5v5h5M17 13.5h.01"/>',invoice:'<path d="M6 3h10l3 3v15l-3-2-3 2-3-2-3 2-2-2V4a1 1 0 0 1 1-1Z"/><path d="M9 8h6M9 12h6M9 16h3"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a5 5 0 0 1 10 0v3m4-18a3 3 0 0 1 0 6m0 5a5 5 0 0 1 4 5v2"/>',report:'<path d="M4 21h17M7 17V9m5 8V4m5 13v-6"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 2 2 2 4-2 3-1 2-4-2-2V8l-4-2-2-3Z"/><circle cx="12" cy="12" r="3"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',export:'<path d="M12 3v12m-4-4 4 4 4-4M5 16v5h14v-5"/>',arrowup:'<path d="m7 17 10-10M7 7h10v10"/>',arrowdown:'<path d="M17 7 7 17M7 7v10h10"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 8-3 8h18s-3-1-3-8M10 21h4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',bank:'<path d="m3 8 9-5 9 5H3Zm2 12h14M7 10v7m5-7v7m5-7v7M3 22h18"/>',cash:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M5 9h.01M19 15h.01"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',print:'<path d="M6 9V3h12v6M6 18H3V9h18v9h-3M6 14h12v7H6Z"/><path d="M17 11h.01"/>',undo:'<path d="M3 11h11a6 6 0 0 1 0 12M3 11l5-5M3 11l5 5"/>',link:'<path d="m10 14 4-4M9 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 10a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-2 2"/>',logout:'<path d="M9 4H4v16h5M10 12h11m-4-4 4 4-4 4"/>',check:'<path d="m4 12 5 5L20 6"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
const pageNames={overview:'Overview',transactions:'Transactions',accounts:'Accounts',invoices:'Invoices',team:'Team & payroll',reports:'Reports',settings:'Settings'};
const kindNames={income:'Income',expense:'Expense',funding:'Owner funding',drawing:'Owner withdrawal',transfer:'Transfer',salary:'Salary'};
const colors=['#8a4cd5','#f4a05d','#5da0e8','#c798e0','#e9c35d','#6fbba6','#a0a8dc'];
let store=new DemoStore(), state=store.state, unsubscribe,period='month',query='',kindFilter='all',accountFilter='all',showReversed=false,menuOpen=false,toastTimer,lastFocus;
let authTab='login',previousAuth={};
function safeStorage(key,value){try{if(value===undefined)return localStorage.getItem(key);localStorage.setItem(key,value);}catch{}return null;}
if(safeStorage('metri.theme')==='dark')document.body.classList.add('theme-dark');
function getPage(){return pageNames[location.hash.slice(1)]?location.hash.slice(1):'overview';}
function canWrite(){return ['owner','accountant'].includes(store.role);}
function bindStore(next){unsubscribe?.();store=next;store.onError=err=>toast('Cloud sync error: '+friendlyError(err),true);unsubscribe=store.subscribe(s=>{state=s;render();});}
function friendlyError(err){const codes={'auth/invalid-credential':'Email ya password sahi nahi hai.','auth/weak-password':'Use a stronger password (at least 12 characters).','auth/email-already-in-use':'This email already has an account. Use Sign in.','auth/operation-not-allowed':'Enable Email/Password sign-in in Firebase Authentication.','permission-denied':'Access denied. Check workspace membership and deployed Firestore rules.','auth/network-request-failed':'Firebase could not be reached. Check your connection.','auth/unauthorized-domain':'Add this website domain in Firebase Authentication authorized domains.'};return codes[err.code]||err.message||'Something went wrong. Please try again.';}
function toast(message,error=false){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}">${e(message)}</div>`;toastTimer=setTimeout(()=>$('#toast-root').innerHTML='',4500);}
function dateLabel(date){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short'}).format(new Date(date+'T12:00:00Z'));}
function longDate(){return new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Karachi'}).format(new Date());}
function accountName(id){return state.accounts.find(a=>a.id===id)?.name||'Account';}
function initial(name){return name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();}
const empty=(label,ico='transactions')=>`<div class="empty">${icon(ico)}${e(label)}</div>`;
function primary(action,label,ico='plus'){return canWrite()?`<button class="btn primary" data-action="${action}">${icon(ico)}${e(label)}</button>`:'';}
function intro(title,subtitle,actions=''){return `<div class="page-intro"><div><div class="eyebrow">${e(longDate())}</div><h1>${e(title)}</h1><p class="subtitle">${e(subtitle)}</p></div><div class="intro-actions">${actions}</div></div>`;}
function periodTabs(){return `<div class="period-control" aria-label="Report period">${[['month','This month'],['30days','30 days'],['year','This year'],['all','All time']].map(([p,l])=>`<button class="${period===p?'active':''}" data-period="${p}" aria-pressed="${period===p}">${l}</button>`).join('')}</div>`;}
function statusStrip(tabs=true){return `<div class="status-strip"><span class="status-label"><i class="status-dot ${store.mode==='firebase'?'live':''}"></i>${store.mode==='demo'?'Demo workspace · illustrative sample data':`Cloud workspace · ${e(store.role)} access`}${!navigator.onLine?' · Offline':''}</span>${tabs?periodTabs():''}</div>`;}
function render(){
  const page=getPage(),s=summary(state,period);
  app.innerHTML=`<div class="layout"><aside class="sidebar ${menuOpen?'open':''}" aria-label="Main navigation"><a class="brand" href="#overview"><img src="./assets/metrisolution-mark.png" alt="MetriSolution logo"><div><div class="brand-name">MetriSolution</div><div class="brand-sub">Company Khata</div></div></a><div class="workspace-selector"><div class="workspace-square">${icon('grid')}</div><div><strong>${e(state.company.name)}</strong><small>${store.mode==='demo'?'Demo company':'Company workspace'}</small></div></div><p class="nav-label">Workspace</p><nav class="nav">${[['overview','grid'],['transactions','transactions'],['accounts','wallet'],['invoices','invoice'],['team','team'],['reports','report']].map(([p,i])=>`<a href="#${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${pageNames[p]}${p==='invoices'&&state.invoices.filter(i=>i.paidPaisa<i.amountPaisa).length?`<span class="nav-badge">${state.invoices.filter(i=>i.paidPaisa<i.amountPaisa).length}</span>`:''}</a>`).join('')}</nav><hr class="sidebar-divider"><p class="nav-label">Manage</p><nav class="nav"><a href="#settings" class="${page==='settings'?'active':''}">${icon('settings')}Settings</a></nav><div class="sidebar-bottom"><div class="sidebar-note"><span class="mini-icon">${icon('shield')}</span><strong>${store.mode==='demo'?'A clearer view of your business.':'Your books, together.'}</strong><p>${store.mode==='demo'?'Explore the workspace, then connect your company to start fresh.':'Your company records sync across your signed-in workspace.'}</p><button data-action="${store.mode==='demo'?'connect':'audit'}">${store.mode==='demo'?'Connect workspace':'View activity'}${icon('arrow')}</button></div><div class="profile"><span class="avatar">${store.mode==='demo'?'MS':initial(store.user.email||'MS')}</span><div><strong>${store.mode==='demo'?'Company owner':e(store.user.email?.split('@')[0])}</strong><small>${store.mode==='demo'?'Demo workspace':e(store.role+' · '+store.id)}</small></div>${icon('down')}</div></div></aside><button class="mobile-scrim" data-action="menu" aria-label="Close navigation"></button><main class="main"><header class="topbar"><button class="icon-button menu-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="${menuOpen}">${icon('menu')}</button><div class="breadcrumb"><span>Workspace</span>${icon('chevron')}<span>${pageNames[page]}</span></div><div class="top-actions"><label class="search-box">${icon('search')}<input id="global-search" placeholder="Search transactions…" aria-label="Search transactions"><span class="shortcut">⌘ K</span></label><div class="top-separator"></div><button class="icon-button" data-action="theme" aria-label="Toggle dark theme">${icon('sun')}</button><button class="icon-button ${s.receivables?'unread':''}" data-action="due" aria-label="View unpaid invoices">${icon('bell')}</button><span class="avatar">MS</span></div></header><div class="content"><p class="print-heading">${e(state.company.name)} · Company Khata · ${longDate()}</p>${renderPage(page)}<footer class="page-footer"><span>© ${new Date().getFullYear()} <strong>MetriSolution</strong> · Your business, in balance.</span><span><i class="footer-dot"></i>${store.mode==='demo'?'Demo data · saved in this browser':'Firebase workspace'} &nbsp; · &nbsp; PKR</span></footer></div></main></div>`;
}
function renderPage(page){return ({overview,transactions:transactionsPage,accounts:accountsPage,invoices:invoicesPage,team:teamPage,reports:reportsPage,settings:settingsPage}[page])();}
function metric(title,value,ico,tone,note,featured=false){return `<section class="card metric ${featured?'featured':''}"><div class="metric-title"><span>${title}</span><span class="metric-icon ${tone}">${icon(ico)}</span></div><div class="metric-value" title="${fullMoney(value)}"><span class="currency">PKR</span>${money(value).length>10?money(value,true):money(value)}</div><div class="metric-bottom">${featured?`<span class="tiny-tag">${state.accounts.length} accounts</span>`:''}${e(note)}</div></section>`;}
function overview(){const s=summary(state,period);return `${intro('Financial overview','A clear picture of what comes in, goes out, and stays.',`<button class="btn" data-action="export">${icon('export')}Export report</button>${primary('add-transaction','Add transaction')}`)}${statusStrip()}<div class="metric-grid">${metric('Available balance',s.balance,'wallet','', 'Across all accounts · all time',true)}${metric('Total income',s.income,'arrowdown','green',`${s.transactions} entries in selected period`)}${metric('Total expenses',s.expenses,'arrowup','orange','Includes recorded salary payments')}${metric('Unpaid invoices',s.receivables,'invoice','blue',`${state.invoices.filter(i=>i.paidPaisa<i.amountPaisa).length} invoices · all time`)}</div><div class="middle-grid">${cashflowCard()}${expenseCard()}</div><div class="bottom-grid"><section class="card table-card"><div class="card-header"><div><h2>Recent transactions</h2><p class="card-subtitle">Your latest company activity</p></div><a class="link-button" href="#transactions">View all${icon('arrow')}</a></div><div class="table-scroll"><table><thead><tr><th>TRANSACTION</th><th>DATE</th><th>AMOUNT</th><th>TYPE</th></tr></thead><tbody>${transactionRows(activeTransactions(state).sort(sortTx).slice(0,5),false)}</tbody></table></div>${!state.transactions.length?empty('Your first transaction starts the story.'):''}<div class="table-footer"><span>Cash basis · recorded payments only</span><span>PKR</span></div></section>${accountsCompact()}</div>`;}
function cashflowCard(){const s=summary(state,period),rows=cashflow(state,period);let a=0,b=0;const points=rows.map(r=>({...r,income:(a+=r.income),expense:(b+=r.expense)}));const max=Math.max(a,b,10000)*1.15,W=600,H=178,left=42,right=18,top=15,bottom=27;const pw=W-left-right,ph=H-top-bottom;const xy=(value,i)=>[left+(points.length<=1?pw:i*pw/(points.length-1)),top+ph-value/max*ph];const line=key=>points.map((p,i)=>`${i?'L':'M'}${xy(p[key],i).join(',')}`).join(' ');const area=key=>`${line(key)} L${W-right},${H-bottom} L${left},${H-bottom}Z`;return `<section class="card"><div class="card-header"><div><h2>Cash flow</h2><p class="card-subtitle">Cumulative income and expenses</p></div><div class="legend"><span class="legend-item"><i class="legend-dot"></i>Income</span><span class="legend-item"><i class="legend-dot orange"></i>Expenses</span></div></div><div class="chart-summary"><div><small>Money in</small><strong>PKR ${money(s.income)}</strong></div><div class="divide"></div><div><small>Money out</small><strong>PKR ${money(s.expenses)}</strong></div><span class="pill">${s.surplus>=0?'+':''}${money(s.surplus,true)} surplus</span></div><div class="chart-area"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Cumulative cash flow. Income ${fullMoney(a)}, expenses ${fullMoney(b)}."><defs><linearGradient id="income-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a47bde" stop-opacity=".12"/><stop offset="1" stop-color="#a47bde" stop-opacity="0"/></linearGradient><linearGradient id="expense-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#f9ae71" stop-opacity=".06"/><stop offset="1" stop-color="#f9ae71" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(f=>`<line class="chart-grid" x1="${left}" x2="${W-right}" y1="${top+ph-f*ph}" y2="${top+ph-f*ph}"/><text class="chart-text" x="${left-9}" y="${top+ph-f*ph+3}" text-anchor="end">${money(Math.round(max*f),true)}</text>`).join('')}${points.length?`<path d="${area('income')}" fill="url(#income-fill)"/><path d="${area('expense')}" fill="url(#expense-fill)"/><path d="${line('income')}" stroke="#8a50d1" stroke-width="2.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="${line('expense')}" stroke="#f3a161" stroke-width="2.3" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`:''}${points.filter((_,i)=>i===0||i===points.length-1||i%Math.max(1,Math.ceil(points.length/7))===0).map(p=>`<text class="chart-text" text-anchor="middle" x="${xy(0,points.indexOf(p))[0]}" y="${H-5}">${p.label}</text>`).join('')}</svg></div><p class="chart-caption">Owner funding, withdrawals and internal transfers are excluded.${period==='all'?' Chart shows the last 12 active months.':''}</p></section>`;}
function expenseCard(){const groups=expenseGroups(state,period),total=groups.reduce((a,[,v])=>a+v,0);let offset=0;const shown=groups.slice(0,4);if(groups.length>4)shown.push(['Other',groups.slice(4).reduce((a,[,v])=>a+v,0)]);return `<section class="card"><div class="card-header"><div><h2>Expense breakdown</h2><p class="card-subtitle">Know where your money goes</p></div><span class="pill">${groups.length} categories</span></div><div class="expense-body"><div class="donut-area"><div class="donut-wrap"><svg viewBox="0 0 140 140" role="img" aria-label="Expense breakdown: ${shown.map(([l,n])=>e(l)+' '+fullMoney(n)).join(', ')}"><circle cx="70" cy="70" r="54" fill="none" stroke="var(--line)" stroke-width="16"/>${shown.map(([,v],i)=>{const pct=v/(total||1)*100,el=`<circle cx="70" cy="70" r="54" fill="none" stroke="${colors[i]}" stroke-width="16" pathLength="100" stroke-dasharray="${Math.max(0,pct-.7)} ${100-Math.max(0,pct-.7)}" stroke-dashoffset="${-offset}" transform="rotate(-90 70 70)"/>`;offset+=pct;return el;}).join('')}</svg><div class="donut-center"><small>Total spent</small><strong>${money(total,true)}</strong><span class="donut-label">PKR</span></div></div><div class="expense-legend">${shown.length?shown.map(([l,n],i)=>`<div class="expense-legend-item"><i class="legend-dot" style="background:${colors[i]}"></i><span title="${e(l)}">${e(l)}</span><strong>${Math.round(n/(total||1)*100)}%</strong></div>`).join(''):'<span class="muted small">No expenses in this period.</span>'}</div></div><div class="insight">${icon('spark')}<span>${groups.length?`${e(groups[0][0])} is your largest expense this period.`:'Add an expense to see your spending mix.'}</span></div></div></section>`;}
function accountsCompact(){const b=balances(state);return `<section class="card"><div class="card-header"><div><h2>Your accounts</h2><p class="card-subtitle">Every rupee, accounted for</p></div><a class="link-button" href="#accounts">Manage${icon('arrow')}</a></div><div class="account-list">${state.accounts.slice(0,3).map(a=>`<div class="account-item"><span class="account-logo ${a.type.toLowerCase()}">${icon(a.type==='Bank'?'bank':a.type==='Cash'?'cash':'wallet')}</span><div><strong>${e(a.name)}</strong><small>${e(a.type)} account</small></div><span class="account-balance">${money(b[a.id])}</span></div>`).join('')||empty('Add your first bank or cash account.','wallet')}</div><div class="account-footer">${icon('shield')}<span>Balances calculated from your ledger · PKR</span></div></section>`;}
function sortTx(a,b){return b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||'')||b.id.localeCompare(a.id);}
function transactionRows(rows,detail=true){return rows.map(t=>{const reversed=state.reversals.some(r=>r.transactionId===t.id),isIn=['income','funding'].includes(t.kind),neutral=t.kind==='transfer';return `<tr class="${reversed?'reversal-row':''}"><td><div class="transaction-description"><span class="tx-symbol ${neutral?'neutral':isIn?'':'out'}">${icon(neutral?'transactions':isIn?'arrowdown':'arrowup')}</span><div><strong>${e(t.description)}</strong><small>${e(t.party||t.category)}</small></div></div></td><td class="muted">${dateLabel(t.date)}</td><td class="amount ${neutral?'':isIn?'in':'out'}">${neutral?'':isIn?'+':'−'}${money(t.amountPaisa)}</td><td><span class="badge ${reversed?'reversed':t.kind}">${reversed?'Reversed':kindNames[t.kind]}</span></td>${detail?`<td class="muted">${e(accountName(t.accountId))}${neutral?' → '+e(accountName(t.toAccountId)):''}</td><td><button class="icon-button" data-action="view-transaction" data-id="${e(t.id)}" aria-label="View ${e(t.description)}">${icon('dots')}</button></td>`:''}</tr>`;}).join('');}
function filteredTx(){return state.transactions.filter(t=>(showReversed||!state.reversals.some(r=>r.transactionId===t.id))&&inPeriod(t,period)&&(kindFilter==='all'||t.kind===kindFilter)&&(accountFilter==='all'||t.accountId===accountFilter||t.toAccountId===accountFilter)&&(!query||[t.description,t.party,t.category,accountName(t.accountId),t.date].some(v=>String(v).toLowerCase().includes(query.toLowerCase())))).sort(sortTx);}
function transactionsPage(){const rows=filteredTx();return `${intro('Transactions','A complete trail of your company’s money movements.',`<button class="btn" data-action="export-ledger">${icon('export')}Export CSV</button>${primary('add-transaction','Add transaction')}`)}${statusStrip()}<div class="toolbar"><input id="tx-search" aria-label="Search ledger" placeholder="Search description, person or category…" value="${e(query)}"><select id="kind-filter" aria-label="Transaction type"><option value="all">All types</option>${Object.entries(kindNames).map(([v,l])=>`<option value="${v}" ${kindFilter===v?'selected':''}>${l}</option>`).join('')}</select><select id="account-filter" aria-label="Account"><option value="all">All accounts</option>${state.accounts.map(a=>`<option value="${e(a.id)}" ${accountFilter===a.id?'selected':''}>${e(a.name)}</option>`).join('')}</select><label class="small muted"><input type="checkbox" id="show-reversed" ${showReversed?'checked':''}> Show reversed</label></div><section class="card table-card"><div class="table-scroll"><table><thead><tr><th>TRANSACTION</th><th>DATE</th><th>AMOUNT · PKR</th><th>TYPE</th><th>ACCOUNT</th><th></th></tr></thead><tbody id="tx-body">${transactionRows(rows)}</tbody></table></div><div id="tx-empty">${!rows.length?empty('No transactions match these filters.'):''}</div><div class="table-footer"><span id="tx-count">${rows.length} entries</span><span>Original entries are preserved when reversed</span></div></section>`;}
function updateTxSearch(){const rows=filteredTx();$('#tx-body').innerHTML=transactionRows(rows);$('#tx-count').textContent=`${rows.length} entries`;$('#tx-empty').innerHTML=rows.length?'':empty('No transactions match these filters.');}
function accountsPage(){const b=balances(state);return `${intro('Company accounts','Bank, cash and digital wallets. One reliable balance.',`${primary('transfer','Transfer money','transactions')}${primary('add-account','Add account')}`)}${statusStrip(false)}<div class="page-grid">${state.accounts.map(a=>`<section class="card account-card"><div class="account-top"><span class="account-logo ${a.type.toLowerCase()}">${icon(a.type==='Bank'?'bank':a.type==='Cash'?'cash':'wallet')}</span><span class="pill">${e(a.type)}</span></div><h2>${e(a.name)}</h2><p class="muted small">Current account balance</p><div class="big-balance"><span class="muted small">PKR</span> ${money(b[a.id])}</div><div class="account-breakdown"><span>Opening balance</span><strong>${fullMoney(a.openingPaisa)}</strong></div><div class="account-breakdown" style="margin-top:10px"><span>Net movement</span><strong>${fullMoney(b[a.id]-a.openingPaisa)}</strong></div></section>`).join('')}</div>${!state.accounts.length?`<section class="card">${empty('Add your first account with its opening balance.','wallet')}</section>`:''}<div class="note">Account balances include all recorded dates. Transfers move money between accounts without changing company income or expenses. Opening balances are fixed; use a documented transaction for later corrections.</div>`;}
function invoicesPage(){return `${intro('Invoices & receivables','Keep track of client balances and every payment received.',primary('add-invoice','Create invoice'))}${statusStrip(false)}<div class="report-stats">${[['Invoiced',state.invoices.reduce((a,i)=>a+i.amountPaisa,0)],['Received',state.invoices.reduce((a,i)=>a+i.paidPaisa,0)],['Outstanding',state.invoices.reduce((a,i)=>a+i.amountPaisa-i.paidPaisa,0)]].map(([l,n])=>`<section class="card settings-card"><p class="muted small">${l} · all time</p><div class="report-number">${fullMoney(n)}</div></section>`).join('')}</div><section class="card table-card"><div class="card-header"><div><h2>Client invoices</h2><p class="card-subtitle">Unpaid invoices do not count as cash income</p></div><span class="pill">${state.invoices.length} total</span></div><div class="table-scroll"><table><thead><tr><th>INVOICE / CLIENT</th><th>DUE DATE</th><th>TOTAL · PKR</th><th>OUTSTANDING</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${[...state.invoices].sort((a,b)=>b.issued.localeCompare(a.issued)).map(i=>`<tr><td><button class="link-button invoice-number" data-action="view-invoice" data-id="${i.id}">${e(i.number)}</button><div class="muted small">${e(i.client)}</div></td><td class="muted">${dateLabel(i.due)}</td><td class="amount">${money(i.amountPaisa)}</td><td class="amount">${money(i.amountPaisa-i.paidPaisa)}</td><td><span class="badge ${invoiceStatus(i)}">${invoiceStatus(i)}</span></td><td>${i.paidPaisa<i.amountPaisa&&canWrite()?`<button class="link-button" data-action="pay-invoice" data-id="${i.id}">Record payment${icon('arrow')}</button>`:`<button class="link-button" data-action="view-invoice" data-id="${i.id}">View invoice${icon('arrow')}</button>`}</td></tr>`).join('')}</tbody></table></div>${!state.invoices.length?empty('Create your first client invoice.','invoice'):''}</section>`;}
function teamPage(){const tx=activeTransactions(state).filter(t=>t.kind==='salary'&&inPeriod(t,'month'));return `${intro('Team & payroll','People behind the work. Payments with a clear record.',primary('add-employee','Add team member'))}${statusStrip(false)}<div class="inline-alert">${icon('clock')} Monthly payroll tracks actual salary payments. Team records are separate from login access.</div><div class="page-grid">${state.employees.map(emp=>{const paid=tx.filter(t=>t.employeeId===emp.id).reduce((a,t)=>a+t.amountPaisa,0),due=Math.max(0,emp.salaryPaisa-paid);return `<section class="card employee-card"><div class="employee-top"><span class="avatar">${e(initial(emp.name))}</span><div><h2>${e(emp.name)}</h2><p class="muted">${e(emp.role)}</p></div></div><div class="salary-row"><span class="muted">Monthly salary</span><strong>${fullMoney(emp.salaryPaisa)}</strong></div><div class="salary-row"><span class="muted">Paid this month</span><strong class="positive">${fullMoney(paid)}</strong></div><div class="salary-progress"><span style="width:${emp.salaryPaisa?Math.min(100,paid/emp.salaryPaisa*100):0}%"></span></div><div class="salary-row"><span class="muted">Remaining this month</span><strong>${fullMoney(due)}</strong></div>${canWrite()?`<button class="btn full ${due?'primary':''}" data-action="pay-salary" data-id="${emp.id}" ${!due?'disabled':''}>${icon(due?'wallet':'check')}${due?'Record salary payment':'Salary settled'}</button>`:''}</section>`;}).join('')}</div>${!state.employees.length?`<section class="card">${empty('Add your team to track monthly salary payments.','team')}</section>`:''}<p class="note">A salary payment is an expense. The monthly salary is a target and does not reduce cash until a payment is recorded. Salary paid is grouped by payment date.</p>`;}
function reportsPage(){const s=summary(state,period),tx=activeTransactions(state).filter(t=>inPeriod(t,period));return `${intro('Business reports','The numbers that help you make your next decision.',`<button class="btn" data-action="print">${icon('print')}Print / PDF</button><button class="btn primary" data-action="export">${icon('export')}Export report</button>`)}${statusStrip()}<div class="report-stats">${[['Operating income',s.income],['Operating expenses',s.expenses],['Operating surplus',s.surplus]].map(([l,n])=>`<section class="card settings-card"><span class="muted small">${l}</span><div class="report-number ${l.includes('surplus')?(n>=0?'positive':'negative'):''}">${fullMoney(n)}</div></section>`).join('')}</div><div class="middle-grid">${cashflowCard()}${expenseCard()}</div><section class="card table-card"><div class="card-header"><h2>Cash movement summary</h2><span class="pill">${tx.length} entries</span></div><table><thead><tr><th>MOVEMENT</th><th style="text-align:right">AMOUNT · PKR</th></tr></thead><tbody>${[['Income received',s.income],['Expenses & salary payments',-s.expenses],['Owner contributions',s.funding],['Owner withdrawals',-s.drawings],['Net cash movement',s.income-s.expenses+s.funding-s.drawings],['Current total cash · all dates',s.balance],['Outstanding invoices · all dates',s.receivables]].map(([l,n])=>`<tr><td>${l}</td><td class="amount" style="text-align:right">${money(n)}</td></tr>`).join('')}</tbody></table></section><p class="note">Cash-basis management report. Unpaid invoices are shown separately; opening balances, owner contributions, withdrawals and internal transfers are excluded from operating surplus. This is a company cashbook, not statutory double-entry accounting.</p>`;}
function settingsPage(){return `${intro('Workspace settings','Make this workspace feel like your company.')}${statusStrip(false)}<div class="settings-grid"><section class="card settings-card"><h2>Company profile</h2><p>Your business name appears in the workspace and exported reports.</p><form id="company-form"><div class="field"><label for="company-name">Company name</label><input id="company-name" name="name" value="${e(state.company.name)}" required maxlength="100" ${store.role!=='owner'?'disabled':''}></div><div class="form-grid"><div class="field"><label>Currency</label><input value="Pakistani Rupee · PKR" disabled></div><div class="field"><label>Business timezone</label><input value="Asia / Karachi" disabled></div></div><button class="btn primary" ${store.role!=='owner'?'disabled':''}>${icon('check')}Save company profile</button><div class="form-error" role="alert"></div></form><div class="note">All amounts are stored as integer paisa to keep financial calculations accurate.</div></section><section class="card settings-card"><h2>${store.mode==='demo'?'Connect your company':'Firebase connected'}</h2><p>${store.mode==='demo'?'The current workspace uses sample records stored in this browser. Connect Firebase to start an empty, shared company workspace.':'You are using an authenticated company workspace. Changes are protected by Firestore membership rules.'}</p><div class="detail-list"><div><dt>Data mode</dt><dd>${store.mode==='demo'?'Browser demo':'Cloud Firestore'}</dd></div><div><dt>Your role</dt><dd>${e(store.role)}</dd></div>${store.mode==='firebase'?`<div><dt>Workspace ID</dt><dd>${e(store.id)}</dd></div><div><dt>Account</dt><dd>${e(store.user.email)}</dd></div>`:''}</div><button class="btn primary" data-action="${store.mode==='demo'?'connect':'logout'}">${icon(store.mode==='demo'?'link':'logout')}${store.mode==='demo'?'Set up Firebase / Sign in':'Sign out to demo'}</button> <a class="btn" href="./guide.html" target="_blank" rel="noopener">Setup guide</a><div class="note">${store.mode==='demo'?'Demo records are never automatically uploaded to Firebase. Your live workspace starts with real entries you add.':'Login access is controlled through company membership. Adding an employee does not grant application access.'}</div></section><section class="card settings-card"><h2>Your brand, throughout.</h2><p>The theme follows your MetriSolution logo, with purple as the primary action color, orange for expenses and blue for account details.</p><div class="token-grid">${[['Purple','#7138CF'],['Orange','#FB9548'],['Blue','#2894ED'],['Canvas','#F7F8FC'],['Sidebar','#211538']].map(([n,c])=>`<div class="color-token"><i style="background:${c};border:1px solid #ddd2"></i>${n}<br>${c}</div>`).join('')}</div><button class="btn" data-action="theme">${icon('sun')}Switch light / dark theme</button></section><section class="card settings-card"><h2>Records & backups</h2><p>Export the full workspace as JSON for record keeping, or use CSV exports for your spreadsheet workflow.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn" data-action="backup">${icon('export')}Download backup</button><button class="btn" data-action="audit">${icon('clock')}Activity log</button></div>${store.mode==='demo'?`<div class="note">Ready to try your own numbers? Clear sample records to start an empty browser workspace. This does not affect Firebase.</div><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn danger" data-action="clear-demo">Clear demo records</button><button class="btn" data-action="reset-demo">Restore sample data</button></div>`:''}</section></div>`;}

function modal(title,subtitle,body,{wide=false,submit}={}){
  lastFocus=document.activeElement;document.body.style.overflow='hidden';
  $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${e(title)}</h2>${subtitle?`<p>${e(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;
  const form=$('#modal-root form');if(form&&submit)form.addEventListener('submit',async ev=>{ev.preventDefault();const error=form.querySelector('.form-error'),button=form.querySelector('button[type="submit"]');if(error){error.textContent='';error.classList.remove('visible');}if(button)button.disabled=true;try{await submit(new FormData(form),form);}catch(err){if(error){error.textContent=friendlyError(err);error.classList.add('visible');}else toast(friendlyError(err),true);}finally{if(button)button.disabled=false;}});
  requestAnimationFrame(()=>$('#modal-root input:not([disabled]), #modal-root select, #modal-root textarea, #modal-root button')?.focus());
}
function closeModal(){const old=$('#modal-root');old.innerHTML='';document.body.style.overflow='';lastFocus?.focus?.();}
function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;}
function select(label,name,options,selected=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,l])=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(l)}</option>`).join('')}</select></div>`;}
const formEnd=(label='Save record')=>`<div class="form-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">${icon('check')}${label}</button></div>`;
function ensureAccounts(){if(!state.accounts.length){toast('Add a company account first.');showAddAccount();return false;}return true;}
function showTransaction(kind='income',employeeId=''){
  if(!canWrite()||!ensureAccounts())return;
  if(kind==='transfer'&&state.accounts.length<2){toast('A transfer needs at least two accounts.');return;}
  if(kind==='salary'&&!state.employees.length){toast('Add a team member first.');showAddEmployee();return;}
  const emp=state.employees.find(x=>x.id===employeeId),paid=emp?activeTransactions(state).filter(t=>t.employeeId===emp.id&&t.kind==='salary'&&inPeriod(t,'month')).reduce((a,t)=>a+t.amountPaisa,0):0;
  modal(kind==='transfer'?'Transfer money':kind==='salary'?'Record salary payment':'Add transaction','Every entry keeps your company balance up to date.',`<form id="transaction-form"><div class="form-grid">${select('Transaction type','kind',Object.entries(kindNames),kind)}${field('Amount · PKR','amount','number',emp?String(Math.max(0,emp.salaryPaisa-paid)/100):'','required min="0.01" step="0.01" max="1000000000" placeholder="0.00"')}${field('Payment date','date','date',today(),`required max="${today()}"`)}${select(kind==='transfer'?'From account':'Account','accountId',state.accounts.map(a=>[a.id,a.name]))}<div class="field full-width"><label for="f-description">Description</label><input id="f-description" name="description" required maxlength="180" placeholder="What was this payment for?" value="${emp?e(emp.name+' · salary payment'):''}"></div><div id="tx-dynamic" class="full-width" style="grid-column:1/-1"></div></div><div class="note">Income and expenses affect operating surplus. Funding, withdrawals and transfers affect cash balances only.</div>${formEnd('Record transaction')}</form>`,{submit:async data=>{const kind=data.get('kind'),emp=state.employees.find(x=>x.id===data.get('employeeId'));const t={kind,amountPaisa:toPaisa(data.get('amount')),date:data.get('date'),description:data.get('description').trim(),accountId:data.get('accountId'),toAccountId:kind==='transfer'?data.get('toAccountId'):'',category:data.get('category')||CATEGORIES[kind][0],party:kind==='salary'?emp?.name||'':data.get('party')?.trim()||'',employeeId:kind==='salary'?data.get('employeeId'):'',invoiceId:''};await store.addTransaction(t);closeModal();toast('Transaction recorded.');}});
  const dynamic=()=>{const k=$('#f-kind').value;$('#tx-dynamic').innerHTML=`<div class="form-grid">${k==='transfer'?select('To account','toAccountId',state.accounts.map(a=>[a.id,a.name]),state.accounts[1]?.id):select('Category','category',CATEGORIES[k].map(c=>[c,c]))}${k==='salary'?select('Team member','employeeId',state.employees.map(x=>[x.id,x.name]),employeeId):k==='transfer'?field('Reference / note','party','text','Internal','maxlength="120"'):field(k==='funding'||k==='drawing'?'Owner / co-founder':'Client / paid to','party','text','','maxlength="120" placeholder="Optional name"')}</div>`;};dynamic();$('#f-kind').addEventListener('change',()=>{if($('#f-kind').value==='salary'&&!state.employees.length){toast('Add a team member first.');$('#f-kind').value='expense';}if($('#f-kind').value==='transfer'&&state.accounts.length<2){toast('Add a second account first.');$('#f-kind').value='expense';}dynamic();});
}
function showAddAccount(){if(!canWrite())return;modal('Add company account','Set the balance before your first recorded transaction.',`<form>${field('Account name','name','text','','required maxlength="80" placeholder="e.g. Business bank"')}<div class="form-grid">${select('Account type','type',[['Bank','Bank'],['Cash','Cash'],['Wallet','Digital wallet']])}${field('Opening balance · PKR','opening','number','0','required min="0" step="0.01" max="1000000000"')}</div>${formEnd('Create account')}</form>`,{submit:async d=>{const opening=/^0(\.0{1,2})?$/.test(d.get('opening').trim())?0:toPaisa(d.get('opening'));await store.addAccount({name:d.get('name').trim(),type:d.get('type'),openingPaisa:opening});closeModal();toast('Account created.');}});}
function showAddEmployee(){if(!canWrite())return;modal('Add team member','Build your company’s payroll roster.',`<form><div class="form-grid">${field('Full name','name','text','','required maxlength="120"')}${field('Role / position','role','text','','required maxlength="120"')}${field('Monthly salary · PKR','salary','number','','required min="0.01" step="0.01" max="1000000000"')}${field('Joining date','joined','date',today(),'required')}${field('Email · optional','email','email','','maxlength="254"')}</div><div class="note">This adds a payroll record. It does not create a user account or grant login access.</div>${formEnd('Add team member')}</form>`,{submit:async d=>{await store.addEmployee({name:d.get('name').trim(),role:d.get('role').trim(),salaryPaisa:toPaisa(d.get('salary')),joined:d.get('joined'),email:d.get('email').trim()});closeModal();toast('Team member added.');}});}
function showInvoice(){if(!canWrite())return;modal('Create client invoice','Track what a client owes. Record cash when payment arrives.',`<form><div class="form-grid">${field('Client / company','client','text','','required maxlength="120"')}${field('Client email · optional','email','email','','maxlength="254"')}<div class="field full-width"><label for="f-title">Service / description</label><input id="f-title" name="title" required maxlength="120" placeholder="e.g. Website development · final milestone"></div>${field('Invoice total · PKR','amount','number','','required min="0.01" step="0.01" max="1000000000"')}${field('Issue date','issued','date',today(),'required')}${field('Payment due','due','date',today(),'required')}</div>${formEnd('Create invoice')}</form>`,{submit:async d=>{await store.addInvoice({client:d.get('client').trim(),email:d.get('email').trim(),title:d.get('title').trim(),amountPaisa:toPaisa(d.get('amount')),issued:d.get('issued'),due:d.get('due')});closeModal();toast('Invoice created.');}});}
function showPayment(id){const i=state.invoices.find(i=>i.id===id);if(!i||!canWrite()||!ensureAccounts())return;modal('Record invoice payment',`${i.number} · ${i.client}`,`<div class="note" style="margin:0 0 20px">Outstanding: <strong>${fullMoney(i.amountPaisa-i.paidPaisa)}</strong></div><form><div class="form-grid">${field('Amount received · PKR','amount','number',String((i.amountPaisa-i.paidPaisa)/100),`required min="0.01" step="0.01" max="${(i.amountPaisa-i.paidPaisa)/100}"`)}${select('Received in','accountId',state.accounts.map(a=>[a.id,a.name]))}${field('Payment date','date','date',today(),`required max="${today()}"`)}</div>${formEnd('Record payment')}</form>`,{submit:async d=>{await store.payInvoice(id,{amountPaisa:toPaisa(d.get('amount')),accountId:d.get('accountId'),date:d.get('date')});closeModal();toast('Payment received and invoice balance updated.');}});}
function showTransactionDetail(id){const t=state.transactions.find(t=>t.id===id);if(!t)return;const reversal=state.reversals.find(r=>r.transactionId===id);modal('Transaction detail',t.description,`<dl class="detail-list">${[['Type',kindNames[t.kind]],['Amount',fullMoney(t.amountPaisa)],['Date',t.date],['Account',accountName(t.accountId)],...(t.toAccountId?[['To account',accountName(t.toAccountId)]]:[]),['Category',t.category],['Person / company',t.party||'—'],['Reference',t.id],['Status',reversal?'Reversed':'Recorded']].map(([l,v])=>`<div><dt>${e(l)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl>${reversal?`<div class="note">Reversal reason: ${e(reversal.reason)}</div>`:canWrite()?`<div class="note">The original entry will remain in your records. Reversing removes its effect on balances${t.invoiceId?' and restores the invoice amount due':''}.</div><form style="margin-top:20px">${field('Reason for reversal','reason','text','','required maxlength="300" placeholder="Explain the correction"')}${formEnd('Reverse entry')}</form>`:''}`,{submit:async d=>{await store.reverseTransaction(id,d.get('reason').trim());closeModal();toast('Entry reversed. Original record preserved.');}});}
function invoiceMarkup(i){return `<div style="display:flex;justify-content:space-between;gap:20px;margin-bottom:25px"><div><h2>${e(state.company.name)}</h2><p class="muted small">Company invoice</p></div><span class="badge ${invoiceStatus(i)}">${invoiceStatus(i)}</span></div><h1 style="font-size:24px">${e(i.number)}</h1><dl class="detail-list">${[['Bill to',i.client],['Email',i.email||'—'],['Issued',i.issued],['Due',i.due]].map(([l,v])=>`<div><dt>${l}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><table><thead><tr><th style="padding-left:12px">DESCRIPTION</th><th>TOTAL · PKR</th></tr></thead><tbody><tr><td style="padding-left:12px;white-space:normal">${e(i.title)}</td><td class="amount">${money(i.amountPaisa)}</td></tr></tbody></table><dl class="detail-list"><div><dt>Total received</dt><dd>${fullMoney(i.paidPaisa)}</dd></div><div><dt>Amount due</dt><dd><strong>${fullMoney(i.amountPaisa-i.paidPaisa)}</strong></dd></div></dl><p class="muted small">Currency: PKR · No tax has been added to this invoice.</p>`;}
function viewInvoice(id){const i=state.invoices.find(i=>i.id===id);if(!i)return;modal('Client invoice',i.number,`${invoiceMarkup(i)}<div class="modal-actions"><button class="btn" data-action="print-invoice" data-id="${i.id}">${icon('print')}Print / PDF</button>${i.paidPaisa<i.amountPaisa&&canWrite()?`<button class="btn primary" data-action="pay-invoice" data-id="${i.id}">Record payment</button>`:''}</div>`);}
function printInvoice(id){const i=state.invoices.find(i=>i.id===id);if(!i)return;const w=window.open('','_blank','width=800,height=850');if(!w){toast('Allow popups to print the invoice.',true);return;}w.opener=null;w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${e(i.number)}</title><style>body{font:14px/1.6 system-ui;color:#24202f;max-width:680px;margin:60px auto;padding:20px}h1,h2,p{margin:0}.muted,dt{color:#8b8095}.small{font-size:12px}.detail-list{margin:28px 0}.detail-list div{display:flex;justify-content:space-between;padding:5px 0}.detail-list dd{margin:0}table{width:100%;text-align:left;border-collapse:collapse}th,td{padding:14px;background:#faf7fd;border-bottom:1px solid #eee}th{font-size:10px}.badge{font-size:12px;color:#7138cf}</style></head><body>${invoiceMarkup(i)}<p style="margin-top:45px;color:#aaa;font-size:11px">Generated from ${e(state.company.name)} Company Khata${store.mode==='demo'?' · Sample invoice':''}</p></body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),200);}
function getSavedConfig(){try{return JSON.parse(safeStorage('metri.firebase')||'null');}catch{return null;}}
function showConnect(tab='login',previous={}){
  authTab=tab;previousAuth=previous;const saved=getSavedConfig(),config=previous.config||JSON.stringify(saved?.config||firebaseConfig||{apiKey:'',authDomain:'',projectId:'',appId:''},null,2);
  modal('Your company workspace','Sign in securely with Firebase Authentication.',`<div class="auth-tabs"><button data-action="auth-login" class="${tab==='login'?'active':''}">Sign in</button><button data-action="auth-create" class="${tab==='create'?'active':''}">Create workspace</button></div><form id="connect-form"><div class="field"><label for="f-config">Firebase web configuration · JSON</label><textarea id="f-config" name="config" required rows="5" spellcheck="false" style="font-family:monospace;font-size:10px">${e(config)}</textarea><span class="help">Paste the web app config from Firebase Project settings. Enable Email/Password Authentication and deploy the supplied Firestore rules first.</span></div><div class="form-grid">${field('Workspace ID','workspaceId','text',previous.workspaceId||saved?.workspaceId||'metrisolution','required pattern="[a-zA-Z0-9_-]{3,100}" maxlength="100"')}${tab==='create'?field('Company name','companyName','text',previous.companyName||'MetriSolution','required maxlength="100"'):''}${field('Email address','email','email',previous.email||'','required autocomplete="username"')}${field('Password','password','password','',`required autocomplete="${tab==='create'?'new-password':'current-password'}" minlength="${tab==='create'?12:6}"`)}</div>${tab==='create'?'<div class="note">Creates a new, empty company and owner account. Sample transactions are not uploaded.</div>':''}${formEnd(tab==='create'?'Create workspace':'Sign in')}</form>`,{wide:true,submit:async d=>{let config;try{config=JSON.parse(d.get('config'));}catch{throw new Error('Configuration must be valid JSON. Use double quotes around keys and values.');}const {connectFirebase}=await import('./firebase-service.js');const next=await connectFirebase(config,{email:d.get('email').trim(),password:d.get('password'),workspaceId:d.get('workspaceId').trim(),create:tab==='create',companyName:d.get('companyName')?.trim()||'MetriSolution'});safeStorage('metri.firebase',JSON.stringify({config,workspaceId:d.get('workspaceId').trim()}));store.destroy();bindStore(next);closeModal();toast('Connected to your company workspace.');}});
}
function showAudit(){modal('Workspace activity','A history of recorded actions.',`<div class="detail-list">${state.audit.slice(0,60).map(a=>`<div style="align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:12px"><div style="display:block;min-width:0"><strong style="font-size:11px">${e(a.action)}</strong><p class="muted small" style="font-size:10px;margin-top:4px;overflow-wrap:anywhere">${e(a.detail)}</p></div><span class="small muted nowrap" style="font-size:9px">${e(a.createdAt?.slice(0,10)||'Now')}</span></div>`).join('')||empty('No activity yet.','clock')}</div>${state.audit.length>60?'<p class="muted small">Showing the latest 60 actions. A JSON backup contains the full log.</p>':''}`);}
function confirmDemoReset(empty){modal(empty?'Clear demo records?':'Restore sample workspace?',empty?'Start with an empty browser workspace.':'Replace browser demo records with fresh sample data.',`<p class="muted small">Download a JSON backup first if you need these records. This only replaces the browser demo.</p><form>${field('Type CONFIRM to continue','confirmation','text','','required pattern="CONFIRM" autocomplete="off"')}${formEnd(empty?'Clear records':'Restore samples')}</form>`,{submit:async d=>{if(d.get('confirmation')!=='CONFIRM')throw new Error('Type CONFIRM to proceed.');await store.reset(empty);closeModal();toast(empty?'Demo records cleared. Add your first account.':'Sample workspace restored.');}});}
function download(name,data,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportLedger(){const rows=getPage()==='transactions'?filteredTx():activeTransactions(state).filter(t=>inPeriod(t,period)).sort(sortTx);download(`MetriSolution_Ledger_${today()}.csv`,'\ufeff'+csv([['Company',state.company.name],['Data mode',store.mode],['Period',period],[],['Date','Type','Description','Party','Category','From account','To account','Amount PKR','Status','Reference'],...rows.map(t=>[t.date,kindNames[t.kind],t.description,t.party,t.category,accountName(t.accountId),t.toAccountId?accountName(t.toAccountId):'',(t.amountPaisa/100).toFixed(2),state.reversals.some(r=>r.transactionId===t.id)?'Reversed':'Recorded',t.id])]));toast('Ledger CSV downloaded.');}
function exportReport(){const s=summary(state,period);download(`MetriSolution_Report_${today()}.csv`,'\ufeff'+csv([['Company',state.company.name],['Data mode',store.mode],['Period',period],['Generated',today()],[],['Metric','Amount PKR'],...Object.entries({'Operating income':s.income,'Operating expenses':s.expenses,'Operating surplus':s.surplus,'Owner funding':s.funding,'Owner withdrawals':s.drawings,'Cash balance (all time)':s.balance,'Receivables (all time)':s.receivables}).map(([k,v])=>[k,(v/100).toFixed(2)]),[],['Expense category','Amount PKR'],...expenseGroups(state,period).map(([k,v])=>[k,(v/100).toFixed(2)])]));toast('Report CSV downloaded.');}
document.addEventListener('click',async ev=>{
  const button=ev.target.closest('[data-action]'),p=ev.target.closest('[data-period]');
  if(p){period=p.dataset.period;render();return;}if(!button)return;
  const action=button.dataset.action,id=button.dataset.id;
  try{switch(action){case 'menu':menuOpen=!menuOpen;render();break;case 'close-modal':closeModal();break;case 'theme':document.body.classList.toggle('theme-dark');safeStorage('metri.theme',document.body.classList.contains('theme-dark')?'dark':'light');break;case 'add-transaction':showTransaction();break;case 'transfer':showTransaction('transfer');break;case 'add-account':showAddAccount();break;case 'add-employee':showAddEmployee();break;case 'pay-salary':showTransaction('salary',id);break;case 'add-invoice':showInvoice();break;case 'pay-invoice':showPayment(id);break;case 'view-transaction':showTransactionDetail(id);break;case 'view-invoice':viewInvoice(id);break;case 'print-invoice':printInvoice(id);break;case 'connect':showConnect();break;case 'auth-login':case 'auth-create':{const f=$('#connect-form'),d=f?Object.fromEntries(new FormData(f)):previousAuth;showConnect(action==='auth-login'?'login':'create',d);break;}case 'logout':await store.signOut();bindStore(new DemoStore());toast('Signed out. Demo workspace opened.');break;case 'export':exportReport();break;case 'export-ledger':exportLedger();break;case 'backup':download(`MetriSolution_Backup_${today()}.json`,JSON.stringify({exportedAt:new Date().toISOString(),dataMode:store.mode,workspace:state},null,2),'application/json');toast('Workspace backup downloaded.');break;case 'print':window.print();break;case 'audit':showAudit();break;case 'due':location.hash='invoices';break;case 'clear-demo':confirmDemoReset(true);break;case 'reset-demo':confirmDemoReset(false);break;}}catch(err){toast(friendlyError(err),true);}
});
document.addEventListener('input',ev=>{if(ev.target.id==='tx-search'){query=ev.target.value;updateTxSearch();}});
document.addEventListener('change',ev=>{if(ev.target.id==='kind-filter'){kindFilter=ev.target.value;render();}if(ev.target.id==='account-filter'){accountFilter=ev.target.value;render();}if(ev.target.id==='show-reversed'){showReversed=ev.target.checked;render();}});
document.addEventListener('submit',async ev=>{if(ev.target.id!=='company-form')return;ev.preventDefault();const form=ev.target,button=form.querySelector('button'),error=form.querySelector('.form-error');button.disabled=true;try{await store.updateCompany(new FormData(form).get('name').trim());toast('Company profile updated.');}catch(err){error.textContent=friendlyError(err);error.classList.add('visible');}finally{button.disabled=false;}});
document.addEventListener('keydown',ev=>{
  if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();$('#global-search')?.focus();}
  if(ev.target.id==='global-search'&&ev.key==='Enter'){query=ev.target.value;kindFilter='all';accountFilter='all';if(getPage()==='transactions')render();else location.hash='transactions';}
  if(ev.key==='Escape'){if($('#modal-root').children.length)closeModal();else if(menuOpen){menuOpen=false;render();}}
  if(ev.key==='Tab'&&$('#modal-root').children.length){const focusable=[...$('#modal-root').querySelectorAll('input:not([disabled]),select:not([disabled]),textarea:not([disabled]),button:not([disabled]),a[href]')];const first=focusable[0],last=focusable.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}
});
window.addEventListener('hashchange',()=>{menuOpen=false;render();window.scrollTo(0,0);});
window.addEventListener('online',()=>{render();toast('Connection restored.');});window.addEventListener('offline',()=>{render();toast(store.mode==='firebase'?'Offline. Reconnect before recording company data.':'Offline. Browser demo is still available.');});
bindStore(store);
const savedConnection=getSavedConfig();
if(savedConnection?.config&&savedConnection.workspaceId){
  import('./firebase-service.js').then(({resumeFirebase})=>resumeFirebase(savedConnection.config,savedConnection.workspaceId)).then(next=>{if(next){store.destroy();bindStore(next);toast('Company workspace restored.');}}).catch(err=>toast('Cloud session could not be restored. Open Settings to sign in. '+friendlyError(err),true));
}
